/**
 * 构造完整纸质审批凭证，浏览器可保存为 PDF。
 * @returns {void} 无返回值。
 */
function centerPrintFull() {
  const r=center.detail;
  const count=Number(localStorage.getItem('approval-print-'+r.id)||0)+1;
  const signature=localStorage.getItem('approval-signature');
  const details=r.amount!==12800&&r.amount!==1334.5?[[r.title,'按业务单据','1 项',r.amount.toFixed(2)]]:r.flow==='采购申请'?[['笔记本电脑','商用 14 英寸','2 台','11,200.00'],['显示器','27 英寸 2K','2 台','1,600.00']]:[['2026-10-08','交通费','深圳往返高铁','686.00'],['2026-10-08','住宿费','深圳酒店 2 晚','560.00'],['2026-10-09','交通费','客户现场往返打车','88.50']];
  const dialog=UI.modal('打印审批单',`<div class="center-print"><div style="display:flex;justify-content:space-between;align-items:center"><b>示例科技有限公司</b><div style="text-align:right;font-size:11px">${r.id}<br>第 ${count} 次打印</div><div style="text-align:center">${UI.icon('qrcode')}<div style="font-size:9px">演示码</div></div></div><h2>${r.flow}审批单 <span style="font-size:13px;font-weight:400">${r.status}</span></h2><table class="center-table"><tr><th>申请人</th><td>${r.person}</td><th>所属部门</th><td>${r.dept}</td></tr><tr><th>业务单号</th><td>${r.key}</td><th>提交时间</th><td>${r.time}</td></tr><tr><th>来源系统</th><td>示例业务系统</td><th>流程版本</th><td>v3</td></tr><tr><th>事由</th><td colspan="3">${esc(r.title)}</td></tr></table><h3 style="margin:22px 0 10px;font-size:14px">${r.flow==='采购申请'?'采购':'费用'}明细</h3><table class="center-table"><thead><tr>${(r.flow==='采购申请'?['物料','规格','数量','金额（元）']:['日期','费用类型','费用说明','金额（元）']).map(t=>`<th>${t}</th>`).join('')}</tr></thead><tbody>${details.map(row=>`<tr>${row.map(v=>`<td>${v}</td>`).join('')}</tr>`).join('')}<tr><th colspan="3">合计${r.amount===1334.5?'：壹仟叁佰叁拾肆元伍角整':''}</th><td>${ApprovalDemo.money(r.amount)}</td></tr></tbody></table><h3 style="margin:22px 0 10px;font-size:14px">审批意见</h3><table class="center-table"><thead><tr><th>节点</th><th>处理人</th><th>意见</th><th>时间 / 签名</th></tr></thead><tbody><tr><td>部门负责人</td><td>李娜</td><td>情况属实，同意。</td><td>2026-10-13 09:45<br><i>李娜</i></td></tr>${(r.history||[]).map(h=>`<tr><td>财务审核</td><td>赵敏</td><td>${esc(h.action)} · ${esc(h.opinion)}</td><td>${esc(h.at)}${signature?`<img src="${signature}" alt="赵敏签名" style="display:block;max-width:90px;height:28px;object-fit:contain">`:''}</td></tr>`).join('')||'<tr><td>财务审核</td><td>赵敏</td><td colspan="2">待处理</td></tr>'}</tbody></table><div style="margin-top:18px;color:#999;font-size:12px;text-align:center">内部审批凭证 · 演示数据</div><div class="center-print-footer"><span>打印人：赵敏 · ${new Date().toLocaleDateString('zh-CN')}</span><span>仅供内部使用 · 第 1 页</span></div></div><p class="hint" style="margin-top:16px">选择「另存为 PDF」可导出原型凭证。演示二维码为占位图，生产版链接到有权限验证的审批详情。</p>`,()=>{localStorage.setItem('approval-print-'+r.id,String(count));window.print();return false;},'打印 / 另存为 PDF');
  dialog.style.width='min(850px,calc(100vw - 32px))';
}
